package com.aistock.notification.alert;
import com.aistock.common.*;import com.fasterxml.jackson.databind.ObjectMapper;import jakarta.servlet.*;import jakarta.servlet.http.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.core.Ordered;import org.springframework.core.annotation.Order;import org.springframework.stereotype.Component;import org.springframework.web.filter.OncePerRequestFilter;import org.springframework.web.util.UrlPathHelper;
/** Independent service authentication occurs before proof parameters/body can be inspected. */
@Component @Order(Ordered.HIGHEST_PRECEDENCE+8)
public final class AlertMarketUseProofAccessFilter extends OncePerRequestFilter {
 private final String token;private final ObjectMapper json;public AlertMarketUseProofAccessFilter(@Value("${aistock.internal.token:}")String token,ObjectMapper json){this.token=token;this.json=json;}
 @Override protected boolean shouldNotFilter(HttpServletRequest r){String p=new UrlPathHelper().getPathWithinApplication(r);return !p.equals("/internal/v1/market-version-use-proofs")&&!p.startsWith("/internal/v1/market-version-use-proofs/");}
 @Override protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain chain)throws IOException,ServletException{s.setHeader("Cache-Control","no-store");var tokens=Collections.list(r.getHeaders("X-Service-Token"));if(token==null||token.isBlank()){deny(r,s,503,"INTERNAL_AUTH_NOT_CONFIGURED");return;}if(tokens.size()!=1||!MessageDigest.isEqual(token.getBytes(StandardCharsets.UTF_8),tokens.get(0).getBytes(StandardCharsets.UTF_8))){deny(r,s,401,"INTERNAL_AUTH_REQUIRED");return;}if(!"GET".equals(r.getMethod())){deny(r,s,404,"RESOURCE_NOT_FOUND");return;}if(r.getInputStream().read()!=-1){deny(r,s,400,"MARKET_VERSION_REQUEST_INVALID");return;}chain.doFilter(r,s);}
 private void deny(HttpServletRequest r,HttpServletResponse s,int status,String code)throws IOException{s.setStatus(status);s.setContentType("application/json;charset=UTF-8");json.writeValue(s.getOutputStream(),ApiResponse.failure(code,"内部终态核验暂不可用",TraceIds.normalize(r.getHeader("X-Trace-Id"))));}
}
